const x402Check = $('1. Screen x402 Endpoint (/v1/verify-merchant)').first().json || {};
const shopCheck = $input.first().json || {};
const injectionRisk = x402Check.prompt_injection_risk || 'UNKNOWN';
const allowWallet = Boolean(x402Check.safe_to_pay) && injectionRisk === 'LOW';
return [{
  json: {
    target_url: x402Check.target_url,
    x402_trust_score: x402Check.trust_score ?? 0,
    prompt_injection_risk: injectionRisk,
    matched_injection_flags: x402Check.matched_flags || [],
    wallet_policy_decision: allowWallet ? 'ALLOW_X402_PAYMENT' : 'HOLD_REQUIRES_HUMAN_APPROVAL',
    merchant_domain: shopCheck.domain,
    merchant_trust_score: shopCheck.trust_score ?? 0,
    merchant_risk_level: shopCheck.risk_level || 'UNKNOWN',
    signed_evidence_issued: Boolean(shopCheck.signed_statement),
    recommendation: x402Check.recommendation || shopCheck.recommendation
  }
}];
